DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "SYS_EF_MIGRATION_HISTORY" WHERE "MigrationId" = '20261030183337_DisbursementRequestWorkflow') THEN
    CREATE TABLE "FCT_INVOICE_BATCHES" (
        "BATCH_ID" bigint GENERATED BY DEFAULT AS IDENTITY,
        "BATCH_NUMBER" character varying(30) NOT NULL,
        "BATCH_REF" character varying(50),
        "BATCH_NAME" character varying(500),
        "BATCH_NAME_AR" character varying(500),
        "CLIENT_ID" bigint NOT NULL,
        "AGREEMENT_ID" bigint,
        "BATCH_DATE" date NOT NULL,
        "SUBMISSION_AT" timestamp with time zone,
        "SUBMISSION_METHOD" character varying(30),
        "SUBMISSION_METHOD_AR" character varying(30),
        "BATCH_TYPE" character varying(30),
        "BATCH_TYPE_AR" character varying(30),
        "CURRENCY_ID" bigint,
        "TOTAL_INVOICES" bigint,
        "TOTAL_GROSS_AMOUNT" numeric(18,2),
        "TOTAL_NET_AMOUNT" numeric(18,2),
        "TOTAL_TAX_AMOUNT" numeric(18,2),
        "VALIDATED_INVOICES" bigint,
        "REJECTED_INVOICES" bigint,
        "APPROVED_INVOICES" bigint,
        "FUNDED_INVOICES" bigint,
        "APPROVED_AMOUNT" numeric(18,2),
        "REJECTED_AMOUNT" numeric(18,2),
        "PROCESSING_START_AT" timestamp with time zone,
        "PROCESSING_END_AT" timestamp with time zone,
        "PROCESSING_DURATION_SEC" bigint,
        "ERROR_COUNT" bigint,
        "WARNING_COUNT" bigint,
        "UPLOAD_FILE_NAME" character varying(500),
        "UPLOAD_FILE_SIZE" integer,
        "UPLOAD_FILE_TYPE" character varying(100),
        "UPLOAD_FILE_CONTENT" bytea,
        "UPLOAD_TEMPLATE_VER" character varying(20),
        "STATUS_ID" bigint,
        "SUBMITTED_BY" character varying(200),
        "VALIDATED_BY" character varying(200),
        "VALIDATION_AT" timestamp with time zone,
        "APPROVED_BY" character varying(200),
        "APPROVAL_AT" timestamp with time zone,
        "REMARKS" character varying(2000),
        "REMARKS_AR" character varying(2000),
        "IS_ACTIVE" boolean NOT NULL,
        "DISBURSEMENT_ID" bigint,
        "CREATED_BY" character varying(100) NOT NULL,
        "CREATED_AT" timestamp with time zone NOT NULL,
        "UPDATED_BY" character varying(100),
        "UPDATED_AT" timestamp with time zone,
        "ROW_VERSION" integer NOT NULL,
        CONSTRAINT "PK_FCT_INVOICE_BATCHES" PRIMARY KEY ("BATCH_ID"),
        CONSTRAINT "FK_FCT_INVOICE_BATCHES_CRM_CLIENTS" FOREIGN KEY ("CLIENT_ID") REFERENCES "CRM_CLIENTS" ("CLIENT_ID") ON DELETE RESTRICT,
        CONSTRAINT "FK_FCT_INVOICE_BATCHES_CRM_LKP_CURRENCIES" FOREIGN KEY ("CURRENCY_ID") REFERENCES "CRM_LKP_CURRENCIES" ("CURRENCY_ID") ON DELETE RESTRICT,
        CONSTRAINT "FK_FCT_INVOICE_BATCHES_CRM_LKP_STATUS_CODES" FOREIGN KEY ("STATUS_ID") REFERENCES "CRM_LKP_STATUS_CODES" ("STATUS_ID") ON DELETE RESTRICT,
        CONSTRAINT "FK_FCT_INVOICE_BATCHES_FCT_DISBURSEMENTS" FOREIGN KEY ("DISBURSEMENT_ID") REFERENCES "FCT_DISBURSEMENTS" ("DISBURSEMENT_ID") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

